func(t time.Time) WorkflowPredicate {
	return func(wf Workflow) bool {
		return wf.CreationTimestamp.After(t)
	}
}

func(t time.Time) WorkflowPredicate {
	return func(wf Workflow) bool {
		return !wf.Status.FinishedAt.IsZero() && wf.Status.FinishedAt.Time.Before(t)
	}
}

